import java.sql.*;public class Read {public static void main(String[]args)throws Exception{try(var c=DriverManager.getConnection(System.getenv("AMA_TEST_DATABASE_URL"),System.getenv("AMA_TEST_DATABASE_USERNAME"),System.getenv("AMA_TEST_DATABASE_PASSWORD"));var s=c.createStatement()){s.setQueryTimeout(2);s.execute("SET NAMES utf8mb4");s.execute("SET time_zone='+00:00'");s.execute("SET SESSION lock_wait_timeout=5");for(String q:new String[]{"SELECT t.id,t.subject_id,t.state,t.attempt,t.last_error,e.id execution_id,e.operation_id,e.state execution_state,o.state operation_state,o.external_result_id FROM durable_task t JOIN meeting m ON m.id=t.subject_id LEFT JOIN external_execution e ON e.task_id=t.id LEFT JOIN external_operation o ON o.id=e.operation_id WHERE m.owner_id='task09-e1e9a4fc-c220-4342-a2ce-22541599f300' ORDER BY t.id LIMIT 10","SELECT r.id,r.execution_id,r.model,r.settled_at FROM model_reservation r WHERE r.model='CONTROLLED_MINUTES_V1' LIMIT 10"}){System.out.println(q);try(var r=s.executeQuery(q)){int n=r.getMetaData().getColumnCount();while(r.next()){for(int i=1;i<=n;i++)System.out.print(r.getMetaData().getColumnLabel(i)+"="+r.getString(i)+" ");System.out.println();}}}}}}